async function runMigrations() {
  const client = await pool.connect();
  try {
    logger.info("Running startup migrations...");
    await client.query(SCHEMA_SQL);
    logger.info("Schema ready");
    const { rows } = await client.query("SELECT COUNT(*) AS n FROM agents");
    if (parseInt(rows[0].n, 10) === 0) {
      await client.query(SEED_AGENTS);
      await client.query(SEED_CHANNELS);
      logger.info("Default agents and channels seeded");
    }
    for (const [id, caps] of Object.entries(AGENT_CAPABILITIES)) {
      await client.query("UPDATE agents SET capabilities = $1 WHERE id = $2", [caps, Number(id)]);
    }
    for (const [oldModel, newModel] of AGENT_MODEL_UPGRADES) {
      await client.query("UPDATE agents SET model = $2 WHERE model = $1", [oldModel, newModel]);
    }
    const NIGHTLY_JOB_NAME = "Nightly Self-Learning Review";
    const NIGHTLY_TASK = `Run the nightly self-learning review. (1) Read today's tool failures and unresolved errors from recent agent activity. (2) For each recurring or unresolved failure, follow the SELF-LEARN protocol: memory_search for a prior lesson, then web_search/web_scrape for a fix if memory has none, then verify the fix actually works. (3) memory_write each VERIFIED lesson in reusable "PROBLEM \u2192 SOLUTION (evidence)" form, tagged "lesson,self-learned,nightly". Store only lessons you actually verified \u2014 never speculation. This makes the swarm permanently smarter overnight.`;
    await client.query(
      `INSERT INTO cron_jobs (agent_id, name, schedule, task, enabled)
       SELECT $1, $2, $3, $4, true
       WHERE NOT EXISTS (SELECT 1 FROM cron_jobs WHERE name = $2)`,
      [1, NIGHTLY_JOB_NAME, "0 4,5,6 * * *", NIGHTLY_TASK]
    );
    const INDEXES = [
      ["idx_messages_channel_id", "messages (channel_id, id)"],
      ["idx_tool_calls_agent_id", "tool_calls (agent_id, id)"],
      ["idx_monologue_agent_id", "monologue_lines (agent_id, id)"],
      ["idx_tasks_status", "tasks (status)"],
      ["idx_tasks_channel_id", "tasks (channel_id)"],
      ["idx_agent_commands_status", "agent_commands (status)"],
      ["idx_agent_commands_to_agent", "agent_commands (to_agent_id)"],
      ["idx_agent_memory_agent_id", "agent_memory (agent_id, created_at)"],
      ["idx_agent_memory_tags", "agent_memory (tags)"],
      ["idx_cron_jobs_enabled_next", "cron_jobs (enabled, next_run_at)"]
    ];
    for (const [name, target] of INDEXES) {
      await client.query(`CREATE INDEX IF NOT EXISTS ${name} ON ${target}`).catch(
        (e) => logger.warn({ err: e, index: name }, "index creation skipped")
      );
    }
  } catch (err) {
    logger.error({ err }, "Migration failed \u2014 continuing anyway");
  } finally {
    client.release();
  }
}

// src/lib/vaultEnv.ts
init_src();
init_vault2();
init_logger2();
async function loadVaultIntoEnv() {
  if (!process.env["SESSION_SECRET"]) {
    logger.warn("Vault\u2192env skipped: SESSION_SECRET is not set");
    return;
  }
  try {
    const rows = await db.select().from(vaultSecretsTable);
    const applied = [];
    const skippedEnvSet = [];
    const undecryptable = [];
    for (const row of rows) {
      const existing = process.env[row.name];
      if (existing != null && existing !== "") {
        skippedEnvSet.push(row.name);
        continue;
      }
      try {
        const value = decryptSecret(row);
        if (value) {
          process.env[row.name] = value;
          applied.push(row.name);
        }
      } catch {
        undecryptable.push(row.name);
      }
    }
    if (undecryptable.length) {
      logger.warn({ undecryptable }, "Vault\u2192env: some secrets could not be decrypted (did SESSION_SECRET change?)");
    }
    logger.info({ applied, skippedEnvSet }, "Loaded vault secrets into environment");
  } catch (err) {
    logger.error({ err }, "Vault\u2192env load failed \u2014 continuing without it");
  }
}

// src/lib/keepAlive.ts
init_logger2();
var DEFAULT_INTERVAL_MS = 10 * 60 * 1e3;
function resolveBaseUrl() {
  const explicit = process.env["KEEP_ALIVE_URL"];
  if (explicit && explicit.trim().length > 0) {
    return explicit.trim();
  }
  const renderUrl = process.env["RENDER_EXTERNAL_URL"];
  if (renderUrl && renderUrl.trim().length > 0) {
    return renderUrl.trim();
  }
  return void 0;
}
function resolveIntervalMs() {
  const raw = process.env["KEEP_ALIVE_INTERVAL_MS"];
  if (!raw) return DEFAULT_INTERVAL_MS;
  const parsed = Number(raw);
  if (Number.isNaN(parsed) || parsed <= 0) {
    logger.warn(
      { raw },
      "Invalid KEEP_ALIVE_INTERVAL_MS \u2014 falling back to default 10 minutes"
    );
    return DEFAULT_INTERVAL_MS;
  }
  return parsed;
}
function startKeepAlive() {
  if (process.env["NODE_ENV"] !== "production") {
    return;
  }
  if (process.env["KEEP_ALIVE_DISABLED"] === "true") {
    logger.info("Keep-alive self-ping disabled via KEEP_ALIVE_DISABLED");
    return;
  }
  const baseUrl = resolveBaseUrl();
  if (!baseUrl) {
    logger.warn(
      "Keep-alive self-ping not started \u2014 set RENDER_EXTERNAL_URL or KEEP_ALIVE_URL to enable it"
    );
    return;
  }
  const intervalMs = resolveIntervalMs();
  const target = `${baseUrl.replace(/\/$/, "")}/api/healthz`;
  const ping = async () => {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 3e4);
    try {
      const res = await fetch(target, {
        method: "GET",
        signal: controller.signal,
        headers: { "user-agent": "bos-aura-keepalive" }
      });
      if (!res.ok) {
        logger.warn({ status: res.status, target }, "Keep-alive ping non-OK");
      } else {
        logger.debug({ target }, "Keep-alive ping ok");
      }
    } catch (err) {
      logger.warn({ err, target }, "Keep-alive ping failed");
    } finally {
      clearTimeout(timeout);
    }
  };
  const timer2 = setInterval(() => {
    void ping();
  }, intervalMs);
  timer2.unref();
  logger.info(
    { target, intervalMs },
    "Keep-alive self-ping started \u2014 preventing Render cold starts"
  );
}

// src/index.ts
init_integrations();
var rawPort = process.env["PORT"];
if (!rawPort) {
  throw new Error(
    "PORT environment variable is required but was not provided."
  );
}
var REQUIRED_KEYS = ["OPENROUTER_API_KEY", "STEEL_API_KEY", "FIRECRAWL_API_KEY"];
var missingKeys = REQUIRED_KEYS.filter((k) => !process.env[k]);
if (missingKeys.length > 0) {
  logger.warn(
    { missingKeys },
    "Missing API key env vars \u2014 AI chat and browser tool routes will fail at runtime"
  );
}
function logIntegrations() {
  const integrations = integrationStatus();
  logger.info(
    {
      configured: integrations.filter((i) => i.configured).map((i) => i.key),
      notConfigured: integrations.filter((i) => !i.configured).map((i) => i.key)
    },
    "Third-party integrations status"
  );
}
var port = Number(rawPort);
if (Number.isNaN(port) || port <= 0) {
  throw new Error(`Invalid PORT value: "${rawPort}"`);
}
runMigrations().then(() => loadVaultIntoEnv()).then(() => logIntegrations()).then(() => reconcileStaleWork()).then(() => {
  app_default.listen(port, (err) => {
    if (err) {
      logger.error({ err }, "Error listening on port");
      process.exit(1);
    }
    logger.info({ port }, "Server listening");
    startKeepAlive();
    startScheduler();
  });
});
